MonitorSnapshot mergeLiveMonitorWithRsBatch(
  MonitorSnapshot live,
  MonitorSnapshot previous,
) {
  final monitor = live.hasPrinterState || !previous.hasPrinterState
      ? live
      : live.copyWithPrinterStatusFrom(previous);
  if (!previous.batchActive || monitor.batchActive) {
    return monitor;
  }
  return monitor.copyWithBatch(
    MobileBatchState(
      active: true,
      itemCode: previous.batchItemCode,
      itemName: previous.batchItemName,
      warehouse: previous.batchWarehouse,
      printMode: previous.batchPrintMode,
      printer: previous.batchPrinter,
      quantitySource: previous.batchQuantitySource,
      manualQtyKg: previous.batchManualQtyKg,
      tareEnabled: previous.batchTareEnabled,
      tareKg: previous.batchTareKg,
    ),
  );
}

String normalizePrinterChoice(String printer) {
  switch (printer.trim().toLowerCase()) {
    case 'godex':
    case 'go-dex':
    case 'g500':
      return 'godex';
    case 'zebra':
    case 'zpl':
    case 'rfid':
    default:
      return 'zebra';
  }
}

String displayPrinterChoice(String printer) {
  return normalizePrinterChoice(printer) == 'godex' ? 'GoDEX' : 'Zebra';
}

String normalizeQuantitySource(String source) {
  return source.trim().toLowerCase() == 'manual' ? 'manual' : 'scale';
}

double? parsePositiveKg(String value) {
  final normalized = value.trim().replaceAll(',', '.');
  if (normalized.isEmpty) {
    return null;
  }
  final parsed = double.tryParse(normalized);
  if (parsed == null || parsed <= 0) {
    return null;
  }
  return parsed;
}

double? parseScaleDisplayKg(String value) {
  final match = RegExp(r'\d+(?:[,.]\d+)?').firstMatch(value.trim());
  if (match == null) {
    return null;
  }
  return parsePositiveKg(match.group(0) ?? '');
}

bool canTriggerGrossPrint({
  required double? grossKg,
  required bool babinaEnabled,
  required String babinaText,
}) {
  if (grossKg == null || grossKg <= 0) {
    return false;
  }
  final double? babinaKg = babinaEnabled ? parsePositiveKg(babinaText) : null;
  if (babinaEnabled && babinaKg == null) {
    return false;
  }
  final netQty = grossKg - (babinaKg ?? 0);
  return grossKg > (babinaKg ?? 0) && netQty >= _minManualPrintKg;
}
